const items = $input.all();
const results = [];

for (const item of items) {
  const html = item.json.data || item.json.body || '';
  const productData = $('Read Product Monitor List').first().json;

  // Extract price using common e-commerce patterns
  const pricePatterns = [
    /"price"\s*:\s*"?([\d.,]+)"?/i,
    /class="price[^"]*"[^>]*>\s*\$?([\d.,]+)/i,
    /itemprop="price"\s+content="([\d.,]+)"/i,
    /data-price="([\d.,]+)"/i,
    /\$([\d,]+\.\d{2})/
  ];

  let competitorPrice = null;
  for (const pattern of pricePatterns) {
    const match = html.match(pattern);
    if (match) {
      competitorPrice = parseFloat(match[1].replace(',', ''));
      break;
    }
  }

  const ownPrice = parseFloat(productData['Our Price'] || 0);
  const priceDiff = competitorPrice ? (ownPrice - competitorPrice).toFixed(2) : null;
  const competitorCheaper = competitorPrice && competitorPrice < ownPrice;

  results.push({
    productName: productData['Product Name'],
    sku: productData.SKU || 'N/A',
    ourPrice: ownPrice,
    competitorPrice: competitorPrice || 'Could not extract',
    competitorName: productData['Competitor Name'] || 'Unknown',
    competitorUrl: productData['Competitor URL'],
    priceDifference: priceDiff,
    competitorCheaper,
    checkedAt: new Date().toISOString()
  });
}

return results.map(r => ({ json: r }));

